/**
 * Money is always stored and calculated as integer piasters (1 EGP = 100 piasters).
 * Only convert to a decimal string at the very edge (display).
 */
export type Piasters = number;

export const PIASTERS_PER_POUND = 100;

export function assertPiasters(value: number): asserts value is Piasters {
  if (!Number.isSafeInteger(value)) {
    throw new RangeError(`Money must be a whole number of piasters, got ${value}`);
  }
}

/** Parse a user-entered amount in pounds ("12.5", "12,50") into piasters. */
export function parsePounds(input: string): Piasters {
  const normalized = input
    .trim()
    .replace(/[٠-٩]/g, (d) => String(d.charCodeAt(0) - 0x0660))
    .replace(/[,٫]/, '.');
  if (!/^-?\d+(\.\d{1,2})?$/.test(normalized)) {
    throw new RangeError(`Invalid amount: "${input}"`);
  }
  const negative = normalized.startsWith('-');
  const [whole, fraction = ''] = normalized.replace('-', '').split('.');
  const piasters = Number(whole) * PIASTERS_PER_POUND + Number(fraction.padEnd(2, '0'));
  return negative ? -piasters : piasters;
}

/** Piasters as an editable pounds string: 6000 -> "60", 6250 -> "62.50". */
export function toPoundsInput(amount: Piasters): string {
  assertPiasters(amount);
  const sign = amount < 0 ? '-' : '';
  const abs = Math.abs(amount);
  const whole = Math.floor(abs / PIASTERS_PER_POUND);
  const fraction = abs % PIASTERS_PER_POUND;
  return `${sign}${whole}${fraction ? '.' + String(fraction).padStart(2, '0') : ''}`;
}

/** Charge for `minutes` at an hourly rate, rounded to the nearest piaster. */
export function chargeForMinutes(minutes: number, pricePerHour: Piasters): Piasters {
  assertPiasters(pricePerHour);
  if (minutes < 0) throw new RangeError('minutes must be >= 0');
  return Math.round((minutes * pricePerHour) / 60);
}

/** Format piasters as a localized EGP amount, e.g. "EGP 12.50" / "١٢٫٥٠ ج.م.‏". */
export function formatMoney(amount: Piasters, locale: string): string {
  assertPiasters(amount);
  return new Intl.NumberFormat(locale, {
    style: 'currency',
    currency: 'EGP',
    minimumFractionDigits: 2,
  }).format(amount / PIASTERS_PER_POUND);
}
